  const start=performance.now(),count=window.__bench.audio.length;
  const poll=setInterval(()=>{if(window.__bench.audio.length>count){clearInterval(poll);clearTimeout(timeout);resolve(Math.round(window.__bench.audio[count]-start));}},10);
