 [...document.querySelectorAll('button')].find(b=>b.textContent==='Pause').click();
 const results=[];
 for(const idea of ['The tortoise has roller skates!', 'Hare, are you ready to race?', 'A duck brings a bright blue race flag.']){
  const input=document.querySelector('#story-idea');
  Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,idea);
  input.dispatchEvent(new Event('input',{bubbles:true}));
  p=waitAudio();
  document.querySelector('.interaction-bar form').requestSubmit();
  results.push({idea,ms:await p});
  [...document.querySelectorAll('button')].find(b=>b.textContent==='Pause').click();
 }
 return {openingMs,results,errors:document.querySelector('.error')?.textContent};
})()
